function meas_out = mfun_gfl_get_measurement(i_c_abc, u_g_line, u_dc, p)
%MFUN_GFL_GET_MEASUREMENT Block get_measurement of the control system.
%   Generated by motulator_export from the MATLAB port of motulator and called by the
%   MATLAB Function block of the library of motulator, whose folder motulator.setup adds
%   to the MATLAB path. The parameters are the fields of the struct p (from the mask, []
%   as NaN).
% Measurements, the DC-bus voltage limited to U_DC_MIN = 1 V
meas = struct( ...
    'i_c_ab', abc2complex(i_c_abc), ...
    'u_g_ab', line2complex(u_g_line), ...
    'u_dc', max(u_dc, 1));
meas_out = grid_measurements_pack(meas);
end

function y = grid_measurements_pack(s)
%GRID_MEASUREMENTS_PACK Signal vector of the struct s.
y = [ ...
    real(s.i_c_ab);
    imag(s.i_c_ab);
    real(s.u_g_ab);
    imag(s.u_g_ab);
    s.u_dc];
end

function u_ab = abc2complex(u)
%ABC2COMPLEX Space vector from the phase quantities u = [u_a u_b u_c].
u_ab = (2/3)*u(1) - (u(2) + u(3))/3 + 1i*(u(2) - u(3))/sqrt(3);
end

function u_ab = line2complex(u)
%LINE2COMPLEX Space vector from the line-to-line quantities u = [u_ab u_bc].
u_ab = (2*u(1) + u(2))/3 + 1i*u(2)/sqrt(3);
end
